        // =====================================================================
        // helpers
        // =====================================================================

        doubleMxN MakeX(int n, int k)
        {
            var X = new doubleMxN(n, k, Allocator.Temp);
            for (int i = 0; i < n; i++)
                for (int c = 0; c < k; c++)
                    X[i, c] = (double)(1 + i - (double)0.5 * c + (double)0.25 * (c + 1) * (i % 3));
            return X;
        }

        doubleN GetCol(in doubleMxN M, int c)
        {
            int n = M.M_Rows;
            var v = new doubleN(n, Allocator.Temp);
            for (int i = 0; i < n; i++) v[i] = M[i, c];
            return v;
        }

        // backward-stable band scaled by matrix magnitude and precision.
        double Band(in doubleMxN A, double factor)
        {
            return (MatMaxAbs(in A) + (double)1) * factor * Consts.doubleSqrtEps;
        }

        double MatMaxAbs(in doubleMxN A)
        {
            double mx = (double)0;
            for (int i = 0; i < A.M_Rows; i++)
                for (int j = 0; j < A.N_Cols; j++)
                {
                    double v = math.abs(A[i, j]);
                    if (v > mx) mx = v;
                }
            return mx;
        }

        void CheckMatClose(in doubleMxN X, in doubleMxN Y, double tol)
        {
            for (int i = 0; i < X.M_Rows; i++)
                for (int c = 0; c < X.N_Cols; c++)
                    AssertClose(X[i, c], Y[i, c], tol);
        }

        void CheckColClose(in doubleMxN X, int c, in doubleN v, double tol)
        {
            for (int i = 0; i < v.N; i++)
                AssertClose(X[i, c], v[i], tol);
        }

        // ‖A·X − B‖ (max abs entry) ≤ band.
        void CheckResidual(in doubleMxN A, in doubleMxN X, in doubleMxN B, double factor)
        {
            var AX = new doubleMxN(A.M_Rows, X.N_Cols, Allocator.Temp);
            Blas.dot(in A, in X, ref AX);
            double tol = Band(in A, factor);
            for (int i = 0; i < B.M_Rows; i++)
                for (int c = 0; c < B.N_Cols; c++)
                    AssertClose(AX[i, c], B[i, c], tol);
        }

        void AssertClose(double a, double b, double precision)
        {
            double diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (double)0)
            {
                Fail[0] = (double)1; Fail[1] = a; Fail[2] = b; Fail[3] = diff;
            }
            Assert.IsTrue(diff <= precision);
        }

        void AssertTrue(bool ok)
        {
            if (!ok && Fail[0] == (double)0)
            {
                Fail[0] = (double)1; Fail[1] = (double)0; Fail[2] = (double)1; Fail[3] = (double)1;
            }
            Assert.IsTrue(ok);
        }

        void RecordEq(int got, int expected)
        {
            if (got != expected && Fail[0] == (double)0)
            {
                Fail[0] = (double)1; Fail[1] = got; Fail[2] = expected; Fail[3] = got - expected;
            }
            Assert.AreEqual(expected, got);
        }
    }

